// agent-pager: forwards OpenCode events to the native macOS notifier.
// Generated by `agent-pager print-config opencode`; install it at
// ~/.config/opencode/plugins/agent-pager.ts
//
// "@opencode/plugin" is built into the opencode binary, so no npm install.
import { Plugin } from "@opencode/plugin"
import { spawn } from "node:child_process"

const BIN = "__AGENT_PAGER_BIN__"

function send(payload: Record<string, unknown>) {
  try {
    const child = spawn(BIN, ["hook", "opencode"], {
      stdio: ["pipe", "ignore", "ignore"],
      detached: true,
    })
    child.on("error", () => {})
    child.stdin?.end(JSON.stringify(payload))
    child.unref()
  } catch {
    // Never let notifications break the session.
  }
}

function text(v: unknown): string | undefined {
  if (typeof v === "string") return v
  if (v && typeof v === "object") {
    const o = v as Record<string, unknown>
    return text(o.message) ?? text(o.data) ?? text(o.name)
  }
  return undefined
}

function describePermission(d: any): string | undefined {
  if (typeof d.message === "string" && d.message) return d.message
  const resources = Array.isArray(d.resources) ? d.resources.join(", ") : ""
  return [d.action, resources].filter(Boolean).join(": ") || undefined
}

export default Plugin.define({
  id: "agent-pager",
  async setup(ctx: any) {
    const controller = new AbortController()
    const own: string | undefined = ctx.location?.directory
    // Subagent sessions finish constantly; only notify for top-level ones.
    const children = new Set<string>()
    // Last assistant text per session, used as the "Stop" one-liner.
    const lastText = new Map<string, string>()

    ;(async () => {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        // OpenCode runs one plugin instance per open project, and every
        // instance sees every event. Only handle our own project's events.
        const dir: string | undefined = event?.location?.directory
        if (dir && own && dir !== own) continue
        const cwd = dir ?? own
        const d: any = event?.data ?? event?.properties ?? {}
        const sid: string | undefined = d.sessionID
        const session = sid
        switch (event?.type) {
          case "session.created":
            if (d.parentID && sid) children.add(sid)
            break
          case "session.text.ended":
            if (sid && typeof d.text === "string" && d.text.trim()) lastText.set(sid, d.text)
            break
          case "session.execution.succeeded":
            if (!sid || !children.has(sid))
              send({ hook_event_name: "finished", cwd, session, message: sid ? lastText.get(sid) : undefined })
            if (sid) lastText.delete(sid)
            break
          case "session.execution.failed":
            if (!sid || !children.has(sid))
              send({ hook_event_name: "error", cwd, session, message: text(d.error) })
            if (sid) lastText.delete(sid)
            break
          case "permission.asked":
            send({ hook_event_name: "permission", cwd, session, message: describePermission(d) })
            break
          case "form.created":
            send({ hook_event_name: "input", cwd, session, message: d.form?.title ?? d.form?.message })
            break
        }
      }
    })().catch(() => {})

    return () => controller.abort()
  },
})
